173	bool OpenSSLTLSContext::good() const { return good_; }
174	
175	bool OpenSSLTLSContext::addCredentialFile(const std::string& certfile,
176	                                          const std::string& keyfile)
177	{
178	  if (keyfile.empty()) {
179	    return addP12CredentialFile(certfile);
180	  }
181	  if (SSL_CTX_use_PrivateKey_file(sslCtx_, keyfile.c_str(), SSL_FILETYPE_PEM) !=
182	      1) {
183	    A2_LOG_ERROR(fmt("Failed to load private key from %s. Cause: %s",
184	                     keyfile.c_str(),
185	                     ERR_error_string(ERR_get_error(), nullptr)));
186	    return false;
187	  }
188	  if (SSL_CTX_use_certificate_chain_file(sslCtx_, certfile.c_str()) != 1) {
189	    A2_LOG_ERROR(fmt("Failed to load certificate from %s. Cause: %s",
190	                     certfile.c_str(),
191	                     ERR_error_string(ERR_get_error(), nullptr)));
192	    return false;
193	  }
194	  A2_LOG_INFO(fmt("Credential files(cert=%s, key=%s) were successfully added.",
195	                  certfile.c_str(), keyfile.c_str()));
196	  return true;
197	}
198	bool OpenSSLTLSContext::addP12CredentialFile(const std::string& p12file)
199	{
200	  std::stringstream ss;
201	  BufferedFile(p12file.c_str(), BufferedFile::READ).transfer(ss);
202	
203	  auto data = ss.str();
204	  void* ptr = const_cast<char*>(data.c_str());
205	  size_t len = data.length();
206	  bio_t bio(BIO_new_mem_buf(ptr, len));
207	
208	  if (!bio) {
209	    A2_LOG_ERROR("Failed to open PKCS12 file: no memory.");
210	    return false;
211	  }
212	  p12_t p12(d2i_PKCS12_bio(bio.get(), nullptr));
213	  if (!p12) {
214	    if (side_ == TLS_SERVER) {
215	      A2_LOG_ERROR(fmt("Failed to open PKCS12 file: %s. "
216	                       "If you meant to use PEM, you'll also have to specify "
217	                       "--rpc-private-key. See the manual.",
218	                       ERR_error_string(ERR_get_error(), nullptr)));
219	    }
220	    else {
221	      A2_LOG_ERROR(fmt("Failed to open PKCS12 file: %s. "
222	                       "If you meant to use PEM, you'll also have to specify "
223	                       "--private-key. See the manual.",
224	                       ERR_error_string(ERR_get_error(), nullptr)));
225	    }
226	    return false;
227	  }
228	  EVP_PKEY* pkey;
229	  X509* cert;
230	  STACK_OF(X509)* ca = nullptr;
231	  if (!PKCS12_parse(p12.get(), "", &pkey, &cert, &ca)) {
232	    if (side_ == TLS_SERVER) {
233	      A2_LOG_ERROR(fmt("Failed to parse PKCS12 file: %s. "
234	                       "If you meant to use PEM, you'll also have to specify "
235	                       "--rpc-private-key. See the manual.",
236	                       ERR_error_string(ERR_get_error(), nullptr)));
237	    }
238	    else {
239	      A2_LOG_ERROR(fmt("Failed to parse PKCS12 file: %s. "
240	                       "If you meant to use PEM, you'll also have to specify "
241	                       "--private-key. See the manual.",
242	                       ERR_error_string(ERR_get_error(), nullptr)));
243	    }
244	    return false;
245	  }
246	
247	  pkey_t pkey_holder(pkey);
248	  x509_t cert_holder(cert);
249	  x509_sk_t ca_holder(ca);
250	
251	  if (!pkey || !cert) {
252	    A2_LOG_ERROR(fmt("Failed to use PKCS12 file: no pkey or cert %s",
253	                     ERR_error_string(ERR_get_error(), nullptr)));
254	    return false;
255	  }
256	  if (!SSL_CTX_use_PrivateKey(sslCtx_, pkey)) {
257	    A2_LOG_ERROR(fmt("Failed to use PKCS12 file pkey: %s",
258	                     ERR_error_string(ERR_get_error(), nullptr)));
259	    return false;
260	  }
261	  if (!SSL_CTX_use_certificate(sslCtx_, cert)) {
262	    A2_LOG_ERROR(fmt("Failed to use PKCS12 file cert: %s",
263	                     ERR_error_string(ERR_get_error(), nullptr)));
264	    return false;
265	  }
266	  if (ca && sk_X509_num(ca) && !SSL_CTX_add_extra_chain_cert(sslCtx_, ca)) {
267	    A2_LOG_ERROR(fmt("Failed to use PKCS12 file chain: %s",
268	                     ERR_error_string(ERR_get_error(), nullptr)));
269	    return false;
270	  }
271	
272	  A2_LOG_INFO("Using certificate and key from PKCS12 file");
273	  return true;
274	}
275	
276	bool OpenSSLTLSContext::addSystemTrustedCACerts()
277	{
278	  if (SSL_CTX_set_default_verify_paths(sslCtx_) != 1) {
279	    A2_LOG_INFO(fmt(MSG_LOADING_SYSTEM_TRUSTED_CA_CERTS_FAILED,
280	                    ERR_error_string(ERR_get_error(), nullptr)));
281	    return false;
282	  }
283	  else {
284	    A2_LOG_INFO("System trusted CA certificates were successfully added.");
285	    return true;
286	  }
287	}
288	
289	bool OpenSSLTLSContext::addTrustedCACertFile(const std::string& certfile)
290	{
291	  if (SSL_CTX_load_verify_locations(sslCtx_, certfile.c_str(), nullptr) != 1) {
292	    A2_LOG_ERROR(fmt(MSG_LOADING_TRUSTED_CA_CERT_FAILED, certfile.c_str(),
293	                     ERR_error_string(ERR_get_error(), nullptr)));
294	    return false;
295	  }
296	  else {
297	    A2_LOG_INFO("Trusted CA certificates were successfully added.");
298	    return true;
299	  }
300	}
301	
302	} // namespace aria2
