147	bool checkIdentity(const SecIdentityRef id, const std::string& fingerPrint,
148	                   const std::vector<std::string> supported)
149	{
150	  CFRef<SecCertificateRef> ref;
151	  SecCertificateRef raw_ref = nullptr;
152	  if (SecIdentityCopyCertificate(id, &raw_ref) != errSecSuccess) {
153	    A2_LOG_ERROR("Failed to get a certref!");
154	    return false;
155	  }
156	  ref.reset(raw_ref);
157	
158	  CFRef<CFDataRef> data(SecCertificateCopyData(ref.get()));
159	  if (!data) {
160	    A2_LOG_ERROR("Failed to get a data!");
161	    return false;
162	  }
163	
164	  // Do try all supported hash algorithms.
165	  // Usually the fingerprint would be sha1 or md5, however this is more
166	  // future-proof. Also "usually" doesn't cut it; there is already software
167	  // using SHA-2 class algos, and SHA-3 is standardized and potential users
168	  // cannot be far.
169	  return std::find_if(std::begin(supported), std::end(supported),
170	                      hash_finder(data.get(), fingerPrint)) !=
171	         std::end(supported);
172	}
