220	bool AppleTLSContext::tryAsFingerprint(const std::string& fingerprint)
221	{
222	  auto fp = stripWhitespace(fingerprint);
223	  // Verify this is a valid hex representation and normalize.
224	  fp = util::toHex(util::fromHex(std::begin(fp), std::end(fp)));
225	
226	  // Verify this can represent a hash
227	  auto ht = MessageDigest::getSupportedHashTypes();
228	  if (std::find_if(std::begin(ht), std::end(ht), hash_validator(fp)) ==
229	      std::end(ht)) {
230	    A2_LOG_INFO(fmt("%s is not a fingerprint, invalid hash representation",
231	                    fingerprint.c_str()));
232	    return false;
233	  }
234	
235	#if defined(__MAC_10_7)
236	  A2_LOG_DEBUG(fmt("Looking for cert with fingerprint %s", fp.c_str()));
237	
238	  // Build and run the KeyChain the query.
239	  CFRef<SecPolicyRef> policy(SecPolicyCreateSSL(true, nullptr));
240	  if (!policy) {
241	    A2_LOG_ERROR("Failed to create SecPolicy");
242	    return false;
243	  }
244	  const void* query_values[] = {kSecClassIdentity, kCFBooleanTrue, policy.get(),
245	                                kSecMatchLimitAll};
246	  CFRef<CFDictionaryRef> query(CFDictionaryCreate(
247	      nullptr, query_keys, query_values, 4, nullptr, nullptr));
248	  if (!query) {
249	    A2_LOG_ERROR("Failed to create identity query");
250	    return false;
251	  }
252	  CFArrayRef identities;
253	  OSStatus err = SecItemCopyMatching(query.get(), (CFTypeRef*)&identities);
254	  if (err != errSecSuccess) {
255	    A2_LOG_ERROR("Query failed: " + errToString(err));
256	    return false;
257	  }
258	
259	  // Alrighty, search the fingerprint.
260	  const size_t nvals = CFArrayGetCount(identities);
261	  for (size_t i = 0; i < nvals; ++i) {
262	    SecIdentityRef id = (SecIdentityRef)CFArrayGetValueAtIndex(identities, i);
263	    if (!id) {
264	      A2_LOG_ERROR("Failed to get a value!");
265	      continue;
266	    }
267	    if (!checkIdentity(id, fp, ht)) {
268	      continue;
269	    }
270	    A2_LOG_INFO("Found cert with matching fingerprint");
271	    credentials_ = id;
272	    CFRetain(id);
273	    return true;
274	  }
275	
276	  A2_LOG_ERROR(
277	      fmt("Failed to lookup %s in your KeyChain", fingerprint.c_str()));
278	  return false;
279	
280	#else // defined(__MAC_10_7)
281	#  if defined(__MAC_10_6)
282	
283	  CFRef<SecIdentitySearchRef> search;
284	  SecIdentitySearchRef raw_search;
285	
286	  // Deprecated as of 10.7
287	  OSStatus err = SecIdentitySearchCreate(0, CSSM_KEYUSE_SIGN, &raw_search);
288	  if (err != errSecSuccess) {
289	    A2_LOG_ERROR("Certificate search failed: " + errToString(err));
290	  }
291	  search.reset(raw_search);
292	
293	  SecIdentityRef id;
294	  while (SecIdentitySearchCopyNext(search, &id) == errSecSuccess) {
295	    if (!checkIdentity(id, fp, ht)) {
296	      continue;
297	    }
298	    A2_LOG_INFO("Found cert with matching fingerprint");
299	    credentials_ = id;
300	    return true;
301	  }
302	
303	  A2_LOG_ERROR(
304	      fmt("Failed to lookup %s in your KeyChain", fingerprint.c_str()));
305	  return false;
306	
307	#  else // defined(__MAC_10_6)
308	
309	  A2_LOG_ERROR("Your system does not support creditials via fingerprints; "
310	               "Upgrade to OSX 10.6 or later");
311	  return false;
312	
313	#  endif // defined(__MAC_10_6)
314	#endif   // defined(__MAC_10_7)
315	}
