171	int OpenSSLTLSSession::handshake(TLSVersion& version)
172	{
173	  ERR_clear_error();
174	  if (tlsContext_->getSide() == TLS_CLIENT) {
175	    rv_ = SSL_connect(ssl_);
176	  }
177	  else {
178	    rv_ = SSL_accept(ssl_);
179	  }
180	  if (rv_ <= 0) {
181	    int sslError = SSL_get_error(ssl_, rv_);
182	    switch (sslError) {
183	    case SSL_ERROR_NONE:
184	    case SSL_ERROR_WANT_X509_LOOKUP:
185	    case SSL_ERROR_ZERO_RETURN:
186	      // TODO Now assume we are doing non-blocking. Then above 2
187	      // errors are OK.
188	      break;
189	    case SSL_ERROR_WANT_READ:
190	    case SSL_ERROR_WANT_WRITE:
191	      return TLS_ERR_WOULDBLOCK;
192	    default:
193	      return TLS_ERR_ERROR;
194	    }
195	  }
196	
197	  switch (SSL_version(ssl_)) {
198	#ifdef TLS1_1_VERSION
199	  case TLS1_1_VERSION:
200	    version = TLS_PROTO_TLS11;
201	    break;
202	#endif // TLS1_1_VERSION
203	
204	#ifdef TLS1_2_VERSION
205	  case TLS1_2_VERSION:
206	    version = TLS_PROTO_TLS12;
207	    break;
208	#endif // TLS1_2_VERSION
209	
210	#ifdef TLS1_3_VERSION
211	  case TLS1_3_VERSION:
212	    version = TLS_PROTO_TLS13;
213	    break;
214	#endif // TLS1_3_VERSION
215	
216	  default:
217	    version = TLS_PROTO_NONE;
218	    break;
219	  }
220	
221	  return TLS_ERR_OK;
222	}
