230	  ret = handshake(version);
231	  if (ret != TLS_ERR_OK) {
232	    return ret;
233	  }
234	  if (tlsContext_->getSide() == TLS_CLIENT && tlsContext_->getVerifyPeer()) {
235	    // verify peer
236	#if OPENSSL_VERSION_NUMBER >= 0x30000000L
237	    auto peerCert = SSL_get1_peer_certificate(ssl_);
