256	    altNames = reinterpret_cast<GENERAL_NAMES*>(
257	        X509_get_ext_d2i(peerCert, NID_subject_alt_name, nullptr, NULL));
258	    if (altNames) {
259	      std::unique_ptr<GENERAL_NAMES, decltype(&GENERAL_NAMES_free)>
260	          altNamesDeleter(altNames, GENERAL_NAMES_free);
261	      size_t n = sk_GENERAL_NAME_num(altNames);
262	      for (size_t i = 0; i < n; ++i) {
263	        const GENERAL_NAME* altName = sk_GENERAL_NAME_value(altNames, i);
264	        if (altName->type == GEN_DNS) {
265	          auto name = ASN1_STRING_get0_data(altName->d.ia5);
266	          if (!name) {
267	            continue;
268	          }
269	          size_t len = ASN1_STRING_length(altName->d.ia5);
270	          if (len == 0) {
271	            continue;
272	          }
273	          if (name[len - 1] == '.') {
274	            --len;
275	            if (len == 0) {
276	              continue;
277	            }
278	          }
279	          dnsNames.push_back(std::string(name, name + len));
280	        }
281	        else if (altName->type == GEN_IPADD) {
282	          const unsigned char* ipAddr = altName->d.iPAddress->data;
283	          if (!ipAddr) {
284	            continue;
285	          }
286	          size_t len = altName->d.iPAddress->length;
287	          ipAddrs.push_back(
288	              std::string(reinterpret_cast<const char*>(ipAddr), len));
289	        }
290	      }
291	    }
292	    X509_NAME* subjectName = X509_get_subject_name(peerCert);
293	    if (!subjectName) {
294	      handshakeErr = "could not get X509 name object from the certificate.";
295	      return TLS_ERR_ERROR;
296	    }
297	    int lastpos = -1;
298	    while (1) {
299	      lastpos =
300	          X509_NAME_get_index_by_NID(subjectName, NID_commonName, lastpos);
301	      if (lastpos == -1) {
302	        break;
303	      }
304	      X509_NAME_ENTRY* entry = X509_NAME_get_entry(subjectName, lastpos);
305	      unsigned char* out;
306	      int outlen = ASN1_STRING_to_UTF8(&out, X509_NAME_ENTRY_get_data(entry));
307	      if (outlen < 0) {
308	        continue;
309	      }
310	      if (outlen == 0) {
311	        OPENSSL_free(out);
312	        continue;
313	      }
314	      if (out[outlen - 1] == '.') {
315	        --outlen;
316	        if (outlen == 0) {
317	          OPENSSL_free(out);
318	          continue;
319	        }
320	      }
321	      commonName.assign(&out[0], &out[outlen]);
322	      OPENSSL_free(out);
323	      break;
324	    }
325	    if (!net::verifyHostname(hostname, dnsNames, ipAddrs, commonName)) {
326	      handshakeErr = "hostname does not match";
327	      return TLS_ERR_ERROR;
328	    }
329	  }
330	
331	  return TLS_ERR_OK;
