339	std::string OpenSSLTLSSession::getLastErrorString()
340	{
341	  if (rv_ <= 0) {
342	    int sslError = SSL_get_error(ssl_, rv_);
343	    switch (sslError) {
344	    case SSL_ERROR_NONE:
345	    case SSL_ERROR_WANT_READ:
346	    case SSL_ERROR_WANT_WRITE:
347	    case SSL_ERROR_WANT_X509_LOOKUP:
348	    case SSL_ERROR_ZERO_RETURN:
349	      return "";
350	    case SSL_ERROR_SYSCALL: {
351	      int err = ERR_get_error();
352	      if (err == 0) {
353	        if (rv_ == 0) {
354	          return "EOF was received";
355	        }
356	        else if (rv_ == -1) {
357	          return "SSL I/O error";
358	        }
359	        else {
360	          return "unknown syscall error";
361	        }
362	      }
363	      else {
364	        return ERR_error_string(err, nullptr);
365	      }
366	    }
367	    case SSL_ERROR_SSL:
368	      return "protocol error";
369	    default:
370	      return "unknown error";
371	    }
372	  }
373	  else {
374	    return "";
375	  }
376	}
