239	{
240	  handshakeErr = "";
241	  for (;;) {
242	    rv_ = gnutls_handshake(sslSession_);
243	    if (rv_ == GNUTLS_E_SUCCESS) {
244	      break;
245	    }
246	    if (rv_ == GNUTLS_E_AGAIN || rv_ == GNUTLS_E_INTERRUPTED) {
247	      return TLS_ERR_WOULDBLOCK;
248	    }
249	    if (gnutls_error_is_fatal(rv_)) {
250	      return TLS_ERR_ERROR;
251	    }
252	  }
253	  if (tlsContext_->getVerifyPeer()) {
254	    // verify peer
255	    gnutls_typed_vdata_st data[] = {
256	        {
257	            GNUTLS_DT_KEY_PURPOSE_OID,
258	            reinterpret_cast<unsigned char*>(
259	                const_cast<char*>(GNUTLS_KP_TLS_WWW_SERVER)),
260	        },
261	    };
262	    unsigned int status;
263	    rv_ = gnutls_certificate_verify_peers(
264	        sslSession_, data, sizeof(data) / sizeof(data[0]), &status);
265	    if (rv_ != GNUTLS_E_SUCCESS) {
266	      return TLS_ERR_ERROR;
267	    }
268	    if (status) {
269	      handshakeErr = "";
270	      if (status & GNUTLS_CERT_INVALID) {
271	        handshakeErr += " `not signed by known authorities or invalid'";
272	      }
273	      if (status & GNUTLS_CERT_REVOKED) {
274	        handshakeErr += " `revoked by its CA'";
275	      }
276	      if (status & GNUTLS_CERT_SIGNER_NOT_FOUND) {
277	        handshakeErr += " `issuer is not known'";
278	      }
279	      // TODO should check GNUTLS_CERT_SIGNER_NOT_CA ?
280	      if (status & GNUTLS_CERT_INSECURE_ALGORITHM) {
281	        handshakeErr += " `insecure algorithm'";
282	      }
283	      if (status & GNUTLS_CERT_NOT_ACTIVATED) {
284	        handshakeErr += " `not activated yet'";
285	      }
286	      if (status & GNUTLS_CERT_EXPIRED) {
287	        handshakeErr += " `expired'";
288	      }
289	      if (status & GNUTLS_CERT_PURPOSE_MISMATCH) {
290	        handshakeErr += " `unsuitable certificate purpose`";
291	      }
292	      // TODO Add GNUTLS_CERT_SIGNATURE_FAILURE here
293	      if (!handshakeErr.empty()) {
294	        return TLS_ERR_ERROR;
295	      }
296	    }
297	    // certificate type: only X509 is allowed.
298	    if (gnutls_certificate_type_get(sslSession_) != GNUTLS_CRT_X509) {
299	      handshakeErr = "certificate type must be X509";
300	      return TLS_ERR_ERROR;
301	    }
302	    unsigned int peerCertsLength;
303	    const gnutls_datum_t* peerCerts;
304	    peerCerts = gnutls_certificate_get_peers(sslSession_, &peerCertsLength);
305	    if (!peerCerts || peerCertsLength == 0) {
306	      handshakeErr = "certificate not found";
307	      return TLS_ERR_ERROR;
308	    }
309	    gnutls_x509_crt_t cert;
310	    rv_ = gnutls_x509_crt_init(&cert);
311	    if (rv_ != GNUTLS_E_SUCCESS) {
312	      return TLS_ERR_ERROR;
313	    }
314	    std::unique_ptr<std::remove_pointer<gnutls_x509_crt_t>::type,
315	                    decltype(&gnutls_x509_crt_deinit)>
316	        certDeleter(cert, gnutls_x509_crt_deinit);
317	    rv_ = gnutls_x509_crt_import(cert, &peerCerts[0], GNUTLS_X509_FMT_DER);
